import{_ as s,c as a,b as p,o as e}from"./app-C4rACRSl.js";const t={};function c(l,n){return e(),a("div",null,n[0]||(n[0]=[p(`<h1 id="java稳定值-stable-values-详解" tabindex="-1"><a class="header-anchor" href="#java稳定值-stable-values-详解"><span>Java稳定值(Stable Values)详解</span></a></h1><h2 id="_1-概述" tabindex="-1"><a class="header-anchor" href="#_1-概述"><span>1. 概述</span></a></h2><p>稳定值(Stable Values)是Java平台引入的一种新特性，旨在解决不可变性与初始化灵活性之间的矛盾。它提供了一种机制，允许对象或字段的初始化延迟到首次使用时，但一旦初始化完成，其值将保持不变且线程安全。</p><h2 id="_2-核心设计理念" tabindex="-1"><a class="header-anchor" href="#_2-核心设计理念"><span>2. 核心设计理念</span></a></h2><h3 id="_2-1-问题背景" tabindex="-1"><a class="header-anchor" href="#_2-1-问题背景"><span>2.1 问题背景</span></a></h3><p>在Java编程中，我们经常面临一个两难选择：</p><ul><li><strong>早期初始化</strong>(如 <code>final</code>字段)：保证了不可变性和线程安全，但可能导致启动性能问题，因为即使某些资源永远不会被使用，也会在对象创建时初始化</li><li><strong>延迟初始化</strong>(如双重检查锁定)：提高了启动性能，但牺牲了不可变性保证，增加了代码复杂性和潜在的并发问题</li></ul><h3 id="_2-2-设计目标" tabindex="-1"><a class="header-anchor" href="#_2-2-设计目标"><span>2.2 设计目标</span></a></h3><p>稳定值的设计旨在提供两全其美的解决方案：</p><ul><li>✅ <strong>延迟初始化</strong>：仅在首次使用时才初始化资源</li><li>✅ <strong>不可变性保证</strong>：一旦初始化完成，值将永远不会改变</li><li>✅ <strong>线程安全</strong>：在多线程环境下保证初始化的原子性和可见性</li><li>✅ <strong>高性能</strong>：通过JVM优化实现接近直接字段访问的性能</li><li>✅ <strong>简单API</strong>：提供直观易用的编程接口</li></ul><h2 id="_3-api详解" tabindex="-1"><a class="header-anchor" href="#_3-api详解"><span>3. API详解</span></a></h2><h3 id="_3-1-基本类型-stablevalue" tabindex="-1"><a class="header-anchor" href="#_3-1-基本类型-stablevalue"><span>3.1 基本类型：StableValue</span></a></h3><p><code>StableValue</code>是稳定值特性的核心类，它提供了最基本的延迟初始化能力：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 创建一个空的稳定值</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> <span class="token function">of</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 仅在稳定值为空时设置值，保证只执行一次</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">T</span> <span class="token function">orElseSet</span><span class="token punctuation">(</span><span class="token class-name">Supplier</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token operator">?</span> <span class="token keyword">extends</span> <span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> supplier<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 创建一个提供稳定值的Supplier</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> <span class="token class-name">Supplier</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> <span class="token function">supplier</span><span class="token punctuation">(</span><span class="token class-name">Supplier</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token operator">?</span> <span class="token keyword">extends</span> <span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> supplier<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-实用方法-stablevalue-supplier" tabindex="-1"><a class="header-anchor" href="#_3-2-实用方法-stablevalue-supplier"><span>3.2 实用方法：StableValue.supplier()</span></a></h3><p>为了简化常见的延迟初始化场景，<code>StableValue</code>提供了静态方法 <code>supplier()</code>：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 直接创建一个Supplier，其get()方法返回稳定值</span></span>
<span class="line"><span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">Supplier</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Logger</span><span class="token punctuation">&gt;</span></span> logger <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">supplier</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token class-name">Logger</span><span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token class-name">OrderController</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 使用时直接调用get()</span></span>
<span class="line">logger<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string">&quot;order started&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-3-批量初始化-stablevalue-list" tabindex="-1"><a class="header-anchor" href="#_3-3-批量初始化-stablevalue-list"><span>3.3 批量初始化：StableValue.list()</span></a></h3><p>对于需要批量创建稳定值的场景，可以使用 <code>list()</code>方法：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> <span class="token function">list</span><span class="token punctuation">(</span><span class="token keyword">int</span> size<span class="token punctuation">,</span> <span class="token class-name">IntFunction</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token operator">?</span> <span class="token keyword">extends</span> <span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> generator<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>使用示例：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">class</span> <span class="token class-name">Application</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token keyword">int</span> <span class="token constant">POOL_SIZE</span> <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span></span>
<span class="line">  </span>
<span class="line">    <span class="token comment">// 创建一个包含10个OrderController实例的列表，每个实例在首次访问时才初始化</span></span>
<span class="line">    <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">OrderController</span><span class="token punctuation">&gt;</span></span> <span class="token constant">CONTROLLER_POOL</span></span>
<span class="line">        <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">list</span><span class="token punctuation">(</span><span class="token constant">POOL_SIZE</span><span class="token punctuation">,</span> i <span class="token operator">-&gt;</span> <span class="token keyword">new</span> <span class="token class-name">OrderController</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  </span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">OrderController</span> <span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">long</span> index <span class="token operator">=</span> <span class="token class-name">Thread</span><span class="token punctuation">.</span><span class="token function">currentThread</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">threadId</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">%</span> <span class="token constant">POOL_SIZE</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token constant">CONTROLLER_POOL</span><span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token keyword">int</span><span class="token punctuation">)</span>index<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-工作原理与性能" tabindex="-1"><a class="header-anchor" href="#_4-工作原理与性能"><span>4. 工作原理与性能</span></a></h2><h3 id="_4-1-内部实现机制" tabindex="-1"><a class="header-anchor" href="#_4-1-内部实现机制"><span>4.1 内部实现机制</span></a></h3><p>稳定值的高效实现依赖于JVM的特殊优化。虽然具体实现可能会随着JDK版本变化，但核心思想是：</p><ol><li><strong>状态标记</strong>：使用特殊的内存布局和标记位来表示稳定值的状态（未初始化、初始化中、已初始化）</li><li><strong>原子操作</strong>：利用CAS等原子操作保证多线程环境下的安全初始化</li><li><strong>稳定内存屏障</strong>：JVM为稳定值访问插入特殊的内存屏障，确保可见性和禁止重排序</li><li><strong>常量折叠优化</strong>：一旦稳定值初始化完成，JVM可以将其视为常量进行优化，如内联值或省略重复检查</li></ol><h3 id="_4-2-性能特性" tabindex="-1"><a class="header-anchor" href="#_4-2-性能特性"><span>4.2 性能特性</span></a></h3><p>稳定值在性能方面具有显著优势：</p><table><thead><tr><th>特性</th><th>稳定值</th><th>双重检查锁定</th><th>final字段</th></tr></thead><tbody><tr><td>启动性能</td><td>优秀（按需初始化）</td><td>优秀</td><td>较差（提前初始化）</td></tr><tr><td>访问性能</td><td>接近final（初始化后）</td><td>较慢（需要volatile读取）</td><td>最快</td></tr><tr><td>线程安全</td><td>内置保证</td><td>需要手动实现</td><td>内置保证</td></tr><tr><td>代码复杂度</td><td>低</td><td>高</td><td>低</td></tr><tr><td>灵活性</td><td>高</td><td>中</td><td>低</td></tr></tbody></table><h3 id="_4-3-与传统方案的对比" tabindex="-1"><a class="header-anchor" href="#_4-3-与传统方案的对比"><span>4.3 与传统方案的对比</span></a></h3><h4 id="final字段" tabindex="-1"><a class="header-anchor" href="#final字段"><span>final字段</span></a></h4><ul><li>优点：简单、线程安全、性能最高</li><li>缺点：必须在对象创建时初始化，可能导致启动缓慢</li></ul><h4 id="双重检查锁定-dcl" tabindex="-1"><a class="header-anchor" href="#双重检查锁定-dcl"><span>双重检查锁定(DCL)</span></a></h4><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">private</span> <span class="token keyword">volatile</span> <span class="token class-name">Logger</span> logger<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token class-name">Logger</span> <span class="token function">getLogger</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>logger <span class="token operator">==</span> <span class="token keyword">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">synchronized</span> <span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>logger <span class="token operator">==</span> <span class="token keyword">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                logger <span class="token operator">=</span> <span class="token class-name">Logger</span><span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token class-name">OrderController</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> logger<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>优点：实现了延迟初始化</li><li>缺点：代码复杂、需要volatile修饰、性能较差（每次访问都需要volatile读取）</li></ul><h4 id="静态内部类-holder模式" tabindex="-1"><a class="header-anchor" href="#静态内部类-holder模式"><span>静态内部类(Holder模式)</span></a></h4><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">class</span> <span class="token class-name">LoggerHolder</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">Logger</span> logger <span class="token operator">=</span> <span class="token class-name">Logger</span><span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token class-name">OrderController</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token class-name">Logger</span> <span class="token function">getLogger</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token class-name">LoggerHolder</span><span class="token punctuation">.</span>logger<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>优点：线程安全、按需初始化</li><li>缺点：仅适用于static字段、每个字段需要单独的Holder类</li></ul><h4 id="稳定值" tabindex="-1"><a class="header-anchor" href="#稳定值"><span>稳定值</span></a></h4><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Logger</span><span class="token punctuation">&gt;</span></span> logger <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token class-name">Logger</span> <span class="token function">getLogger</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> logger<span class="token punctuation">.</span><span class="token function">orElseSet</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token class-name">Logger</span><span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token class-name">OrderController</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>优点：线程安全、按需初始化、适用于实例和静态字段、代码简洁、性能优秀</li><li>缺点：需要JDK 25+并启用预览特性</li></ul><h2 id="_5-适用场景" tabindex="-1"><a class="header-anchor" href="#_5-适用场景"><span>5. 适用场景</span></a></h2><p>稳定值特别适合以下场景：</p><h3 id="_5-1-资源密集型组件" tabindex="-1"><a class="header-anchor" href="#_5-1-资源密集型组件"><span>5.1 资源密集型组件</span></a></h3><p>对于需要大量资源或耗时操作的组件，如日志记录器、数据库连接池、配置解析器等：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">DatabaseService</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 数据库连接池仅在首次使用时初始化</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">DataSource</span><span class="token punctuation">&gt;</span></span> dataSource <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">Connection</span> <span class="token function">getConnection</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">SQLException</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> dataSource<span class="token punctuation">.</span><span class="token function">orElseSet</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token class-name">HikariConfig</span> config <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">HikariConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            config<span class="token punctuation">.</span><span class="token function">setJdbcUrl</span><span class="token punctuation">(</span><span class="token string">&quot;jdbc:mysql://localhost:3306/mydb&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            config<span class="token punctuation">.</span><span class="token function">setUsername</span><span class="token punctuation">(</span><span class="token string">&quot;user&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            config<span class="token punctuation">.</span><span class="token function">setPassword</span><span class="token punctuation">(</span><span class="token string">&quot;password&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">// 其他配置...</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">HikariDataSource</span><span class="token punctuation">(</span>config<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 这可能是一个昂贵的操作</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getConnection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-条件性使用的组件" tabindex="-1"><a class="header-anchor" href="#_5-2-条件性使用的组件"><span>5.2 条件性使用的组件</span></a></h3><p>对于可能永远不会被使用的组件：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">UserService</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 只有当需要发送通知时，才初始化邮件客户端</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">EmailClient</span><span class="token punctuation">&gt;</span></span> emailClient <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">updateUser</span><span class="token punctuation">(</span><span class="token class-name">User</span> user<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 更新用户信息...</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 只有当用户开启了通知时，才发送邮件</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>user<span class="token punctuation">.</span><span class="token function">isNotificationEnabled</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            emailClient<span class="token punctuation">.</span><span class="token function">orElseSet</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token class-name">EmailClient</span> client <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">EmailClient</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                client<span class="token punctuation">.</span><span class="token function">setHost</span><span class="token punctuation">(</span><span class="token string">&quot;smtp.example.com&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                client<span class="token punctuation">.</span><span class="token function">setPort</span><span class="token punctuation">(</span><span class="token number">587</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token comment">// 其他配置...</span></span>
<span class="line">                client<span class="token punctuation">.</span><span class="token function">connect</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 连接邮件服务器</span></span>
<span class="line">                <span class="token keyword">return</span> client<span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">sendNotification</span><span class="token punctuation">(</span><span class="token string">&quot;User updated&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Your profile has been updated.&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-3-批量初始化优化" tabindex="-1"><a class="header-anchor" href="#_5-3-批量初始化优化"><span>5.3 批量初始化优化</span></a></h3><p>对于需要创建多个可能不会全部使用的对象：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">ServiceLocator</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">Map</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">,</span> <span class="token class-name">Supplier</span><span class="token punctuation">&lt;</span><span class="token class-name">Service</span><span class="token punctuation">&gt;</span><span class="token punctuation">&gt;</span></span> <span class="token constant">SERVICES</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">HashMap</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  </span>
<span class="line">    <span class="token keyword">static</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 注册各种服务，但仅在首次请求时初始化</span></span>
<span class="line">        <span class="token constant">SERVICES</span><span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string">&quot;userService&quot;</span><span class="token punctuation">,</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">supplier</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token keyword">new</span> <span class="token class-name">UserServiceImpl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token constant">SERVICES</span><span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string">&quot;orderService&quot;</span><span class="token punctuation">,</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">supplier</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token keyword">new</span> <span class="token class-name">OrderServiceImpl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token constant">SERVICES</span><span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string">&quot;paymentService&quot;</span><span class="token punctuation">,</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">supplier</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token keyword">new</span> <span class="token class-name">PaymentServiceImpl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token comment">// 更多服务...</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  </span>
<span class="line">    <span class="token annotation punctuation">@SuppressWarnings</span><span class="token punctuation">(</span><span class="token string">&quot;unchecked&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">T</span> <span class="token keyword">extends</span> <span class="token class-name">Service</span><span class="token punctuation">&gt;</span></span> <span class="token class-name">T</span> <span class="token function">getService</span><span class="token punctuation">(</span><span class="token class-name">String</span> name<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">Supplier</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Service</span><span class="token punctuation">&gt;</span></span> supplier <span class="token operator">=</span> <span class="token constant">SERVICES</span><span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>supplier <span class="token operator">==</span> <span class="token keyword">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ServiceNotFoundException</span><span class="token punctuation">(</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token class-name">T</span><span class="token punctuation">)</span> supplier<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_6-最佳实践" tabindex="-1"><a class="header-anchor" href="#_6-最佳实践"><span>6. 最佳实践</span></a></h2><h3 id="_6-1-声明为final" tabindex="-1"><a class="header-anchor" href="#_6-1-声明为final"><span>6.1 声明为final</span></a></h3><p>始终将 <code>StableValue</code>变量声明为 <code>final</code>，以确保其不可变性：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 正确：声明为final</span></span>
<span class="line"><span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Logger</span><span class="token punctuation">&gt;</span></span> logger <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 错误：可被重新赋值</span></span>
<span class="line"><span class="token keyword">private</span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Logger</span><span class="token punctuation">&gt;</span></span> logger <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-2-避免副作用" tabindex="-1"><a class="header-anchor" href="#_6-2-避免副作用"><span>6.2 避免副作用</span></a></h3><p>稳定值的初始化逻辑应该是幂等的，避免产生副作用：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 不推荐：初始化有副作用</span></span>
<span class="line"><span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Connection</span><span class="token punctuation">&gt;</span></span> connection <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">Connection</span> conn <span class="token operator">=</span> dataSource<span class="token punctuation">.</span><span class="token function">getConnection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    conn<span class="token punctuation">.</span><span class="token function">setAutoCommit</span><span class="token punctuation">(</span><span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 副作用</span></span>
<span class="line">    <span class="token keyword">return</span> conn<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 推荐：将副作用移到使用时</span></span>
<span class="line"><span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Connection</span><span class="token punctuation">&gt;</span></span> connection <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span>dataSource<span class="token operator">::</span><span class="token function">getConnection</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">void</span> <span class="token function">useConnection</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">Connection</span> conn <span class="token operator">=</span> connection<span class="token punctuation">.</span><span class="token function">orElseSet</span><span class="token punctuation">(</span>dataSource<span class="token operator">::</span><span class="token function">getConnection</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    conn<span class="token punctuation">.</span><span class="token function">setAutoCommit</span><span class="token punctuation">(</span><span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 在使用时设置</span></span>
<span class="line">    <span class="token comment">// 使用连接...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-3-注意异常处理" tabindex="-1"><a class="header-anchor" href="#_6-3-注意异常处理"><span>6.3 注意异常处理</span></a></h3><p>初始化逻辑可能会抛出异常，需要适当处理：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Config</span><span class="token punctuation">&gt;</span></span> config <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token class-name">Config</span><span class="token punctuation">.</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string">&quot;app.properties&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">IOException</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">UncheckedIOException</span><span class="token punctuation">(</span><span class="token string">&quot;Failed to load config&quot;</span><span class="token punctuation">,</span> e<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-4-选择合适的初始化方式" tabindex="-1"><a class="header-anchor" href="#_6-4-选择合适的初始化方式"><span>6.4 选择合适的初始化方式</span></a></h3><p>根据场景选择合适的初始化方式：</p><ol><li><strong>声明位置初始化</strong>：适用于初始化逻辑简单、依赖明确的场景</li><li><strong>getter方法初始化</strong>：适用于初始化逻辑复杂、可能依赖其他状态的场景</li><li><strong>Supplier形式</strong>：适用于需要与现有API集成的场景</li></ol><h2 id="_7-局限性与注意事项" tabindex="-1"><a class="header-anchor" href="#_7-局限性与注意事项"><span>7. 局限性与注意事项</span></a></h2><h3 id="_7-1-初始化异常" tabindex="-1"><a class="header-anchor" href="#_7-1-初始化异常"><span>7.1 初始化异常</span></a></h3><p>如果初始化逻辑抛出异常，稳定值将保持未初始化状态，下次调用 <code>orElseSet()</code>时会重新尝试初始化：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">StableValue</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Resource</span><span class="token punctuation">&gt;</span></span> resource <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">void</span> <span class="token function">useResource</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">Resource</span> r <span class="token operator">=</span> resource<span class="token punctuation">.</span><span class="token function">orElseSet</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 可能抛出异常</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name">System</span><span class="token punctuation">.</span><span class="token function">currentTimeMillis</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">%</span> <span class="token number">2</span> <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">RuntimeException</span><span class="token punctuation">(</span><span class="token string">&quot;Random failure&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Resource</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token comment">// 使用资源...</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">RuntimeException</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 处理异常</span></span>
<span class="line">        logger<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token string">&quot;Failed to initialize resource&quot;</span><span class="token punctuation">,</span> e<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-2-内存泄漏风险" tabindex="-1"><a class="header-anchor" href="#_7-2-内存泄漏风险"><span>7.2 内存泄漏风险</span></a></h3><p>稳定值一旦初始化，其引用将永远不会被释放。如果稳定值引用了大量资源，且这些资源不再被使用，可能导致内存泄漏：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 潜在的内存泄漏：大对象可能永远不会被回收</span></span>
<span class="line"><span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">StableValue</span><span class="token operator">&lt;</span><span class="token keyword">byte</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token operator">&gt;</span> largeBuffer <span class="token operator">=</span> <span class="token class-name">StableValue</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token keyword">new</span> <span class="token keyword">byte</span><span class="token punctuation">[</span><span class="token number">1024</span> <span class="token operator">*</span> <span class="token number">1024</span> <span class="token operator">*</span> <span class="token number">1024</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_8-未来展望" tabindex="-1"><a class="header-anchor" href="#_8-未来展望"><span>8. 未来展望</span></a></h2><p>稳定值特性仍在不断发展中，未来可能会有以下改进：</p><ol><li><strong>更广泛的JVM优化</strong>：进一步提高稳定值的访问性能，使其接近或达到final字段的性能</li><li><strong>更多集合类型支持</strong>：除了List外，可能会添加Map、Set等集合类型的稳定值支持</li><li><strong>集成到语言层面</strong>：可能会考虑在Java语言层面添加对稳定值的原生支持，如特殊的关键字或语法</li><li><strong>更好的工具支持</strong>：IDE和静态分析工具可能会添加对稳定值的特殊支持，如自动补全、警告和重构</li></ol><h2 id="_9-总结" tabindex="-1"><a class="header-anchor" href="#_9-总结"><span>9. 总结</span></a></h2><p>稳定值是Java平台解决不可变性与初始化灵活性之间矛盾的重要创新。它通过提供简单、安全、高性能的延迟初始化机制，帮助开发人员编写更高效、更可维护的代码。</p><p>稳定值的核心优势包括：</p><ul><li><strong>简单易用的API</strong>：减少了延迟初始化的代码复杂性</li><li><strong>内置线程安全</strong>：无需手动实现同步机制</li><li><strong>高性能</strong>：初始化后接近final字段的访问性能</li><li><strong>灵活性</strong>：支持多种初始化方式和使用场景</li></ul><p>随着稳定值特性的不断成熟和普及，它有望成为Java开发中延迟初始化的首选方案，帮助开发人员构建更高效、更可靠的应用程序。</p>`,80)]))}const i=s(t,[["render",c]]),u=JSON.parse('{"path":"/java/new-features/stable-values.html","title":"Java稳定值(Stable Values)详解","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1766714992000,"contributors":[{"name":"zhaomy","username":"zhaomy","email":"3036190149@qq.com","commits":1,"url":"https://github.com/zhaomy"}],"changelog":[{"hash":"424a5c73af2efb41f59e150224db57220a228f1a","time":1766714992000,"email":"3036190149@qq.com","author":"zhaomy","message":"docs(java): 添加稳定值特性文档并更新介绍文件"}]},"filePathRelative":"java/new-features/stable-values.md","excerpt":"\\n<h2>1. 概述</h2>\\n<p>稳定值(Stable Values)是Java平台引入的一种新特性，旨在解决不可变性与初始化灵活性之间的矛盾。它提供了一种机制，允许对象或字段的初始化延迟到首次使用时，但一旦初始化完成，其值将保持不变且线程安全。</p>\\n<h2>2. 核心设计理念</h2>\\n<h3>2.1 问题背景</h3>\\n<p>在Java编程中，我们经常面临一个两难选择：</p>\\n<ul>\\n<li><strong>早期初始化</strong>(如 <code>final</code>字段)：保证了不可变性和线程安全，但可能导致启动性能问题，因为即使某些资源永远不会被使用，也会在对象创建时初始化</li>\\n<li><strong>延迟初始化</strong>(如双重检查锁定)：提高了启动性能，但牺牲了不可变性保证，增加了代码复杂性和潜在的并发问题</li>\\n</ul>"}');export{i as comp,u as data};
